    /**
     * Method to retrieve the Risk via an FindRiskQuery
     * @return 	query	FindRiskQuery
     */
    @SuppressWarnings("unused")
    public Risk find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Risk - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
